+				? adapter.updateRoutine(input.routineId, { routine: payload })
+				: adapter.updateRoutine(
+						input.routineId,
+						{ routine: payload },
+						options,
+					);
+		const response = yield* request;
+		return {
+			routine: normalizeRoutineResponse(response),
+			usesRepRanges,
+		};
+	});
